package cn.nemo.qingxiao;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import java.util.*;
public class DayReminder extends BroadcastReceiver {
 static PendingIntent alarm(Context c,String key){return PendingIntent.getBroadcast(c,key.hashCode(),new Intent(c,DayReminder.class).setAction(key),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c){try{JSONArray prefs=new JSONObject(Store.read(c)).optJSONArray("preferences");AlarmManager m=c.getSystemService(AlarmManager.class);for(String key:new String[]{"planReminder","reviewReminder"}){m.cancel(alarm(c,key));if(prefs==null)continue;String value="";for(int i=0;i<prefs.length();i++){JSONObject p=prefs.getJSONObject(i);if(("pref:"+key).equals(p.optString("id"))&&!p.optBoolean("deleted"))value=p.optString("value");}if(!value.matches("\\d{2}:\\d{2}"))continue;String[] parts=value.split(":");Calendar at=Calendar.getInstance();at.set(Calendar.HOUR_OF_DAY,Integer.parseInt(parts[0]));at.set(Calendar.MINUTE,Integer.parseInt(parts[1]));at.set(Calendar.SECOND,0);at.set(Calendar.MILLISECOND,0);if(at.getTimeInMillis()<=System.currentTimeMillis())at.add(Calendar.DAY_OF_MONTH,1);if(Build.VERSION.SDK_INT<31||m.canScheduleExactAlarms())m.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at.getTimeInMillis(),alarm(c,key));else m.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at.getTimeInMillis(),alarm(c,key));}}catch(Exception e){}}
 public void onReceive(Context c,Intent in){boolean review="reviewReminder".equals(in.getAction());NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("daily","每日计划与回顾",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent pi=PendingIntent.getActivity(c,review?301:300,new Intent(c,MainActivity.class).putExtra("review",review),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify(review?301:300,new Notification.Builder(c,"daily").setSmallIcon(R.drawable.ic_notification).setContentTitle(review?"回顾今天的完成与时间使用":"安排今天的重要事项").setContentText("轻效 Todo · "+(review?"打开番茄时间表，看看时间花在了哪里。":"挑选重要事项，为它们预估番茄数。")).setContentIntent(pi).setAutoCancel(true).build());schedule(c);}
}
